import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#world');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
const scene=new THREE.Scene();scene.background=new THREE.Color('#a9c5bd');scene.fog=new THREE.FogExp2('#a9c5bd',.009);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,180);const hemi=new THREE.HemisphereLight('#e7f2dc','#495b3f',2.05);scene.add(hemi);const sun=new THREE.DirectionalLight('#ffe3ae',3.3);sun.position.set(-25,38,18);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-42;sun.shadow.camera.right=42;sun.shadow.camera.top=42;sun.shadow.camera.bottom=-42;sun.shadow.bias=-.0003;scene.add(sun);
const mat=(color,rough=.9)=>new THREE.MeshStandardMaterial({color,roughness:rough});
const mats={grass:mat('#68915b'),grass2:mat('#789c63'),dirt:mat('#745b3c'),bark:mat('#65452e'),bark2:mat('#80563a'),leaf:mat('#527c4f'),leaf2:mat('#6a9256'),leaf3:mat('#89a963'),stone:mat('#7d8880'),stone2:mat('#a0a49a'),crystal:mat('#74c8c0',.32),gold:mat('#e5c777',.35),wood:mat('#98734b'),wood2:mat('#b18a59'),water:new THREE.MeshStandardMaterial({color:'#78b4b1',roughness:.24,metalness:.1,transparent:true,opacity:.75}),enemy:mat('#8ebf72',.44),white:mat('#eee8d7'),dark:mat('#303a34')};
const boxGeo=new THREE.BoxGeometry(1,1,1);const sphereGeo=new THREE.SphereGeometry(1,8,6);const world={size:38,half:19,ground:null,resources:[],enemies:[],builds:[]};
function terrainHeight(x,z){const r=Math.sin(x*.29)*.7+Math.cos(z*.27)*.62+Math.sin((x+z)*.17)*.55;return Math.max(0,Math.round((r+1.4)*.5))*1.15;}
function addMesh(parent,geometry,material,x,y,z,sx=1,sy=1,sz=1){const m=new THREE.Mesh(geometry,material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function makeGround(){const cells=world.size*world.size;const geo=new THREE.BoxGeometry(2,2,2);const grass=new THREE.InstancedMesh(geo,mats.grass,cells);const soil=new THREE.InstancedMesh(geo,mats.dirt,cells);grass.receiveShadow=soil.receiveShadow=true;const dummy=new THREE.Object3D();let n=0;for(let x=-world.half;x<world.half;x++)for(let z=-world.half;z<world.half;z++){const h=terrainHeight(x,z);dummy.position.set(x*2,h-1,z*2);dummy.updateMatrix();soil.setMatrixAt(n,dummy.matrix);dummy.position.y=h;dummy.updateMatrix();grass.setMatrixAt(n,dummy.matrix);n++;}grass.instanceMatrix.needsUpdate=true;soil.instanceMatrix.needsUpdate=true;grass.castShadow=false;soil.castShadow=false;scene.add(soil,grass);world.ground=grass;}
function markResource(group,type,label,amount){group.userData={resource:type,label,amount,collected:false};group.traverse(o=>{if(o.isMesh)o.userData.root=group;});scene.add(group);world.resources.push(group);}
function makeTree(x,z,large=false){const g=new THREE.Group(),y=terrainHeight(x,z);g.position.set(x*2,y,z*2);const h=large?3.5:2.6;addMesh(g,boxGeo,mats.bark,0,h*.48,0,.7,h,.7);addMesh(g,boxGeo,mats.bark2,-.28,h*.48,.18,.18,h*.78,.18);for(const [dx,dy,dz,s,material] of [[0,h+1,0,1.5,mats.leaf],[.8,h+.5,.2,1.1,mats.leaf2],[-.7,h+.55,-.25,1.18,mats.leaf],[.1,h+1.8,.1,1.05,mats.leaf3],[0,h+.45,-.75,.9,mats.leaf2]])addMesh(g,boxGeo,material,dx,dy,dz,s,s,s);markResource(g,'madeira','Madeira',3+Math.floor(Math.random()*2));}
function makeStone(x,z,type='pedra'){const g=new THREE.Group(),y=terrainHeight(x,z);g.position.set(x*2,y,z*2);const stones=type==='cristal'?[[0,.55,0,.5,1.5,.5],[-.55,.4,.12,.43,.8,.42],[.5,.35,-.2,.36,.7,.42]]:[[0,.43,0,1,.8,.9],[-.45,.29,.26,.56,.58,.58],[.45,.3,-.25,.56,.6,.6]];stones.forEach((v,i)=>{const m=addMesh(g,boxGeo,type==='cristal'?(i===0?mats.crystal:mats.gold):(i===1?mats.stone2:mats.stone),v[0],v[1],v[2],v[3],v[4],v[5]);m.rotation.y=i*.4;if(type==='cristal')m.rotation.z=(i-1)*.17;});markResource(g,type,type==='cristal'?'Cristal':'Pedra',type==='cristal'?1:2);}
function makeBush(x,z){const g=new THREE.Group(),y=terrainHeight(x,z);g.position.set(x*2,y,z*2);addMesh(g,boxGeo,mats.leaf2,0,.35,0,1.1,.65,1.1);for(let i=0;i<4;i++){const berry=addMesh(g,sphereGeo,mat('#c66b54'),(Math.random()-.5)*.8,.46,(Math.random()-.5)*.8,.1,.1,.1);berry.userData.berry=true;}markResource(g,'fibra','Fibra',2);}
function makeWorld(){makeGround();const water=new THREE.Mesh(new THREE.PlaneGeometry(34,22),mats.water);water.rotation.x=-Math.PI/2;water.position.set(-24,.92,9);water.receiveShadow=true;scene.add(water);for(let i=0;i<95;i++){let x=Math.floor(Math.random()*34-17),z=Math.floor(Math.random()*34-17);if(Math.hypot(x,z)<5)continue;const roll=Math.random();if(roll<.47)makeTree(x,z,Math.random()<.25);else if(roll<.76)makeStone(x,z);else if(roll<.89)makeStone(x,z,'cristal');else makeBush(x,z);}for(let i=0;i<70;i++){const x=Math.random()*76-38,z=Math.random()*76-38;if(Math.abs(x)>19||Math.abs(z)>19)continue;if(Math.hypot(x,z)<7)continue;const y=terrainHeight(x/2,z/2);const g=new THREE.Group();g.position.set(x,y,z);addMesh(g,boxGeo,Math.random()<.5?mats.grass2:mats.leaf3,0,.08,0,.12,.24,.12);g.rotation.y=Math.random()*3;scene.add(g);}}
makeWorld();
const player=new THREE.Group();player.position.set(0,terrainHeight(0,0),0);scene.add(player);const avatar=new THREE.Group();player.add(avatar);
const skin=mat('#d7aa83'),tunic=mat('#879a6d'),pants=mat('#445448'),capeMat=mat('#a54e3e'),leather=mat('#6f5034');
const torso=addMesh(avatar,boxGeo,tunic,0,1.32,0,.72,.95,.42);torso.castShadow=true;const head=addMesh(avatar,boxGeo,skin,0,2.04,0,.48,.5,.46);addMesh(avatar,boxGeo,mat('#493c2d'),0,2.31,-.02,.52,.14,.5);const legL=addMesh(avatar,boxGeo,pants,-.2,.48,0,.25,.72,.3),legR=addMesh(avatar,boxGeo,pants,.2,.48,0,.25,.72,.3);const armL=addMesh(avatar,boxGeo,skin,-.5,1.38,0,.2,.73,.23),armR=addMesh(avatar,boxGeo,skin,.5,1.38,0,.2,.73,.23);const cape=addMesh(avatar,boxGeo,capeMat,0,1.32,-.3,.62,.9,.13);const weapon=new THREE.Group();avatar.add(weapon);const blade=addMesh(weapon,boxGeo,mat('#d3d8c6',.3),.55,1.38,.05,.11,.8,.12);addMesh(weapon,boxGeo,mats.gold,.55,1.02,.05,.38,.1,.16);weapon.visible=false;
const classes={guerreiro:{name:'Guerreiro',avatar:'✦',hp:120,mana:70,speed:7.5,ability:'Ímpeto',color:'#9c5443'},mago:{name:'Mago',avatar:'✧',hp:85,mana:120,speed:7,ability:'Orbe arcano',color:'#7582bc'},arqueira:{name:'Arqueira',avatar:'⌁',hp:95,mana:90,speed:9,ability:'Disparo veloz',color:'#648e5b'}};let chosen='guerreiro',started=false,inventory={madeira:0,pedra:0,cristal:0,fibra:0},hp=100,mana=100,xp=0,level=1,stamina=100,buildMode=false,buildType='piso',keys={},yaw=0,pitch=.22,attackUntil=0,abilityReady=0,dayTime=0,target=null,toastTimer,notificationTimer,moveVelocity=new THREE.Vector3(),jumpV=0,onGround=true,lastTime=performance.now(),mouseDown=false,muted=true;const raycaster=new THREE.Raycaster(),screenCenter=new THREE.Vector2(0,0),clock=new THREE.Clock();
const $=s=>document.querySelector(s);const toast=(text)=>{const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100);};const notify=(text)=>{const el=$('#notification');el.textContent=text;el.classList.add('show');clearTimeout(notificationTimer);notificationTimer=setTimeout(()=>el.classList.remove('show'),2400);};
function updateBars(){const c=classes[chosen];$('#health-fill').style.width=`${Math.max(0,hp/c.hp*100)}%`;$('#health-label').textContent=Math.ceil(hp);$('#mana-fill').style.width=`${Math.max(0,mana/c.mana*100)}%`;$('#mana-label').textContent=Math.ceil(mana);$('#xp-fill').style.width=`${xp}%`;$('#xp-label').textContent=`${xp} / 100`;$('#hero-class').textContent=`${c.name.toUpperCase()} · NÍVEL ${level}`;$('#objective-count').textContent=`${Math.min(3,inventory.madeira)}/3`;$('#objective-fill').style.width=`${Math.min(100,inventory.madeira/3*100)}%`;$('#wood-count').textContent=inventory.madeira;$('#stone-count').textContent=inventory.pedra;$('#crystal-count').textContent=inventory.cristal;$('#fiber-count').textContent=inventory.fibra;$('#objective-text').textContent=inventory.madeira>=3?'Construa um piso para seu refúgio':'Colete madeira para começar';}
function chooseClass(id){chosen=id;document.querySelectorAll('.class-card').forEach(b=>b.classList.toggle('selected',b.dataset.class===id));}
document.querySelectorAll('.class-card').forEach(b=>b.addEventListener('click',()=>chooseClass(b.dataset.class)));
$('#start-button').addEventListener('click',()=>{started=true;const c=classes[chosen];hp=c.hp;mana=c.mana;$('#hero-name').textContent=chosen==='mago'?'A Guardiã':chosen==='arqueira'?'A Exploradora':'Aventureiro';$('#hero-avatar').textContent=c.avatar;$('#hero-avatar').style.color=c.color;$('#hero-class').textContent=`${c.name.toUpperCase()} · NÍVEL 1`;$('#ability-name').textContent=c.ability;$('#title-screen').classList.add('hidden');$('#hud').classList.remove('hidden');$('#crosshair-prompt').classList.remove('hidden');updateBars();notify(`O Vale do Alces aguarda, ${c.name.toLowerCase()}.`);});
function setBuild(type){buildType=type;document.querySelectorAll('.build-item').forEach(b=>b.classList.toggle('active',b.dataset.build===type));}
document.querySelectorAll('.build-item').forEach(b=>b.addEventListener('click',()=>setBuild(b.dataset.build)));
$('#build-toggle').addEventListener('click',()=>{buildMode=!buildMode;$('#build-toggle').classList.toggle('active',buildMode);toast(buildMode?'Modo construção ativado':'Modo construção encerrado');});
$('#sound-button').addEventListener('click',()=>{muted=!muted;$('#sound-button').textContent=muted?'♫':'♪';notify(muted?'Som desativado':'Som ativado');});
function updateTarget(){raycaster.setFromCamera(screenCenter,camera);const objects=[];world.resources.forEach(r=>{if(!r.userData.collected)objects.push(r);});const hits=raycaster.intersectObjects(objects,true);let found=null;for(const h of hits){const root=h.object.userData.root;if(root&&root.userData.resource){found=root;break;}}if(found&&found.position.distanceTo(player.position)<7){target=found;$('#interact-hint').classList.remove('hidden');$('#hint-target').textContent=found.userData.label;}else{target=null;$('#interact-hint').classList.add('hidden');}}
function collect(){if(!target||target.userData.collected)return;const r=target;const d=r.position.distanceTo(player.position);if(d>7){toast('Chegue mais perto');return;}r.userData.collected=true;const type=r.userData.resource;inventory[type]+=r.userData.amount;xp+=12;if(xp>=100){xp-=100;level++;hp=Math.min(classes[chosen].hp,hp+20);mana=Math.min(classes[chosen].mana,mana+20);notify(`Nível ${level}! Sua jornada fica mais forte.`);}const labels={madeira:'madeira',pedra:'pedra',cristal:'cristal',fibra:'fibra'};toast(`+${r.userData.amount} ${labels[type]}  ·  +12 XP`);scene.remove(r);target=null;$('#interact-hint').classList.add('hidden');updateBars();}
function placeBuild(){raycaster.setFromCamera(screenCenter,camera);const hit=raycaster.intersectObject(world.ground)[0];if(!hit){toast('Aponte para o terreno');return;}const point=hit.point;const gx=Math.round(point.x/2)*2,gz=Math.round(point.z/2)*2;if(player.position.distanceTo(new THREE.Vector3(gx,player.position.y,gz))>12){toast('Muito longe para construir');return;}let cost,type;if(buildType==='piso'){cost={madeira:3};type='piso';}else if(buildType==='parede'){cost={pedra:3};type='parede';}else{cost={madeira:2,pedra:2};type='fogueira';}if(Object.entries(cost).some(([k,v])=>inventory[k]<v)){toast('Recursos insuficientes');return;}Object.entries(cost).forEach(([k,v])=>inventory[k]-=v);const y=terrainHeight(Math.round(gx/2),Math.round(gz/2));const g=new THREE.Group();g.position.set(gx,y+.06,gz);if(type==='piso'){addMesh(g,boxGeo,mats.wood,0,.12,0,1.9,.24,1.9);for(let z=-.65;z<=.65;z+=.65)addMesh(g,boxGeo,mats.wood2,0,.245,z,1.8,.035,.035);}if(type==='parede'){addMesh(g,boxGeo,mats.stone,0,1,0,1.85,2, .28);addMesh(g,boxGeo,mats.stone2,-.4,1.3,.17,.45,.28,.05);}if(type==='fogueira'){for(let i=0;i<3;i++){const log=addMesh(g,boxGeo,mats.bark,0,.2,0,1.1,.18,.18);log.rotation.y=i*Math.PI/3;}const flame=addMesh(g,sphereGeo,mat('#e88c43',.4),0,.55,0,.28,.48,.28);flame.userData.flame=true;addMesh(g,sphereGeo,mat('#ffe18b',.48),0,.48,0,.14,.3,.14);}scene.add(g);world.builds.push(g);updateBars();xp+=5;toast(type==='piso'?'Piso construído!':'Construção concluída!');}
function showCombat(text){const el=$('#combat-message');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),700);}
function attack(){if(!started||buildMode)return;const now=performance.now();if(now<attackUntil)return;attackUntil=now+470;weapon.visible=true;weapon.rotation.z=-.8;setTimeout(()=>{weapon.rotation.z=.45;setTimeout(()=>weapon.visible=false,140);},90);let nearest=null,dist=5;for(const e of world.enemies){if(e.userData.dead)continue;const d=e.position.distanceTo(player.position);if(d<dist){dist=d;nearest=e;}}if(nearest){damageEnemy(nearest,chosen==='guerreiro'?35:chosen==='arqueira'?28:20);showCombat('✦  ACERTOU!');}else showCombat('');}
function useAbility(){const now=performance.now();if(now<abilityReady){toast('Habilidade recarregando');return;}if(mana<20){toast('Mana insuficiente');return;}mana-=20;abilityReady=now+4500;$('#ability-cooldown').style.width='100%';setTimeout(()=>$('#ability-cooldown').style.width='0',4500);if(chosen==='guerreiro'){const dir=new THREE.Vector3(Math.sin(yaw),0,Math.cos(yaw));player.position.add(dir.multiplyScalar(3.2));player.position.y=terrainHeight(player.position.x/2,player.position.z/2);for(const e of world.enemies)if(e.position.distanceTo(player.position)<4)damageEnemy(e,35);showCombat('ÍMPETO');}else if(chosen==='mago'){const orb=addMesh(scene,sphereGeo,mat('#9cb7ff',.24),player.position.x,player.position.y+1.4,player.position.z,.32,.32,.32);const dir=new THREE.Vector3(Math.sin(yaw),0,Math.cos(yaw));let traveled=0;const tick=()=>{if(!orb.parent)return;orb.position.addScaledVector(dir,.55);traveled+=.55;for(const e of world.enemies)if(!e.userData.dead&&e.position.distanceTo(orb.position)<1.5){damageEnemy(e,55);scene.remove(orb);return;}if(traveled>18){scene.remove(orb);return;}requestAnimationFrame(tick);};tick();showCombat('ORBE ARCANO');}else{const dir=new THREE.Vector3(Math.sin(yaw),0,Math.cos(yaw));let nearest=null,dist=18;for(const e of world.enemies){const d=e.position.distanceTo(player.position);if(!e.userData.dead&&d<dist){nearest=e;dist=d;}}if(nearest){damageEnemy(nearest,50);showCombat('DISPARO VELOZ');}else showCombat('DISPARO VELOZ');}updateBars();}
function damageEnemy(e,amount){if(e.userData.dead)return;e.userData.hp-=amount;e.scale.setScalar(1.22);setTimeout(()=>{if(e.parent)e.scale.setScalar(1);},120);if(e.userData.hp<=0){e.userData.dead=true;scene.remove(e);world.enemies=world.enemies.filter(x=>x!==e);inventory.cristal++;xp+=25;updateBars();toast('Guardião derrotado · +1 cristal · +25 XP');}}
function makeEnemy(x,z){const g=new THREE.Group();const y=terrainHeight(x/2,z/2);g.position.set(x,y,z);g.userData={hp:70,dead:false,home:new THREE.Vector3(x,y,z),phase:Math.random()*5};const body=addMesh(g,sphereGeo,mats.enemy,0,.55,0,.7,.55,.7);addMesh(g,sphereGeo,mats.white,-.23,.7,.53,.13,.14,.08);addMesh(g,sphereGeo,mats.white,.23,.7,.53,.13,.14,.08);addMesh(g,sphereGeo,mats.dark,-.23,.7,.6,.055,.07,.04);addMesh(g,sphereGeo,mats.dark,.23,.7,.6,.055,.07,.04);scene.add(g);world.enemies.push(g);}
for(let i=0;i<7;i++){const a=Math.random()*Math.PI*2,r=14+Math.random()*22,x=Math.cos(a)*r,z=Math.sin(a)*r;makeEnemy(x,z);}
function updateEnemies(dt,t){for(const e of world.enemies){const delta=new THREE.Vector3(player.position.x-e.position.x,0,player.position.z-e.position.z),d=delta.length();if(d<9){delta.normalize();e.position.addScaledVector(delta,dt*(d<2?0:1.55));e.rotation.y=Math.atan2(delta.x,delta.z);if(d<1.6&&Math.random()<dt*.55){hp=Math.max(0,hp-5);updateBars();toast('Um slime atingiu você!');}}else{e.position.x=e.userData.home.x+Math.sin(t*.6+e.userData.phase)*1.5;e.position.z=e.userData.home.z+Math.cos(t*.5+e.userData.phase)*1.5;}e.position.y=terrainHeight(e.position.x/2,e.position.z/2)+Math.abs(Math.sin(t*2+e.userData.phase))*.12;}}
function updatePlayer(dt,t){const forward=Number(!!keys.KeyW||!!keys.ArrowUp)-Number(!!keys.KeyS||!!keys.ArrowDown),side=Number(!!keys.KeyD||!!keys.ArrowRight)-Number(!!keys.KeyA||!!keys.ArrowLeft);let speed=classes[chosen].speed;if(keys.ShiftLeft||keys.ShiftRight){if(stamina>0){speed*=1.5;stamina=Math.max(0,stamina-dt*20);}}else stamina=Math.min(100,stamina+dt*12);const dir=new THREE.Vector3(Math.sin(yaw),0,Math.cos(yaw)),right=new THREE.Vector3(dir.z,0,-dir.x);const move=dir.multiplyScalar(forward).add(right.multiplyScalar(side));if(move.lengthSq()>0){move.normalize();player.position.addScaledVector(move,speed*dt);player.rotation.y=Math.atan2(move.x,move.z);const swing=Math.sin(t*12)*.08;legL.rotation.x=forward||side?swing:0;legR.rotation.x=forward||side?-swing:0;armL.rotation.x=forward||side?-swing:0;cape.rotation.x=.08+Math.sin(t*9)*.025;}const max=world.half*2-2;player.position.x=THREE.MathUtils.clamp(player.position.x,-max,max);player.position.z=THREE.MathUtils.clamp(player.position.z,-max,max);if(keys.Space&&onGround){jumpV=7;onGround=false;}player.position.y+=jumpV*dt;jumpV-=19*dt;const floor=terrainHeight(player.position.x/2,player.position.z/2);if(player.position.y<floor){player.position.y=floor;jumpV=0;onGround=true;} }
function updateCamera(dt){const targetPos=new THREE.Vector3(player.position.x,player.position.y+1.35,player.position.z);const distance=chosen==='arqueira'?8.1:7.3;const offset=new THREE.Vector3(-Math.sin(yaw)*distance,3.8+pitch*3, -Math.cos(yaw)*distance);camera.position.lerp(targetPos.clone().add(offset),1-Math.pow(.001,dt));camera.lookAt(targetPos.clone().add(new THREE.Vector3(Math.sin(yaw)*2,.2,Math.cos(yaw)*2)));}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.04,(now-lastTime)/1000);lastTime=now;const t=now/1000;if(started){updatePlayer(dt,t);updateCamera(dt);updateTarget();updateEnemies(dt,t);dayTime+=dt;const cycle=(Math.sin(dayTime*.025)+1)*.5;sun.intensity=2.1+cycle*1.6;scene.fog.color.setRGB(.55+cycle*.12,.68+cycle*.1,.65+cycle*.1);scene.background.copy(scene.fog.color);$('#weather-label').textContent=cycle>.66?'TARDE DOURADA · DIA 01':cycle<.18?'CREPÚSCULO · DIA 01':'MANHÃ SERENA · DIA 01';}renderer.render(scene,camera);}
